const event = $json;
const entryPoints = event.conferenceData?.entryPoints ?? [];
const videoEntry = entryPoints.find((entry) => entry.entryPointType === 'video')?.uri;
const text = `${event.location ?? ''} ${event.description ?? ''}`;
const textLink = text.match(/https:\/\/(?:meet\.google\.com|zoom\.us|[^\s]+\.zoom\.us|teams\.microsoft\.com)\/[^\s<>]+/i)?.[0];
const meetingLink = event.hangoutLink ?? videoEntry ?? textLink;
if (!meetingLink) throw new Error('This calendar event does not contain a supported HTTPS meeting link.');
const occurrence = event.start?.dateTime ?? event.start?.date ?? 'unknown-start';
return [{ json: {
  meetingLink,
  deduplicationKey: `google-calendar:${event.id}:${occurrence}`,
  customAttributes: {
    source: 'n8n_google_calendar',
    calendar_event_id: event.id,
    event_start: occurrence,
    event_title: event.summary ?? ''
  }
} }];
